import sys

def solve() -> None:
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))

    zero_b = []          # (a, t)
    positive_b = []      # (a, b, t)

    for _ in range(N):
        a = int(next(it))
        b = int(next(it))
        t = int(next(it))
        if b == 0:
            if a > 0:               # only positive fun matters
                zero_b.append((a, t))
        else:
            if a > 0:               # otherwise first ride is non‑positive
                positive_b.append((a, b, t))

    Q = int(next(it))
    queries = [int(next(it)) for _ in range(Q)]

    if not queries:
        return

    maxT = max(queries)
    if maxT == 0:
        # all times are zero
        for _ in queries:
            sys.stdout.write("0\n")
        return

    dp = [0] * (maxT + 1)

    # ----- unbounded items (b == 0) -----
    for a, t in zero_b:
        if t > maxT:
            continue
        for time in range(t, maxT + 1):
            cand = dp[time - t] + a
            if cand > dp[time]:
                dp[time] = cand

    # ----- bounded groups (b > 0) -----
    for a, b, t in positive_b:
        if t > maxT:
            # cannot even take one ride
            continue

        # compute maximal number of rides with positive fun
        K = 0
        while True:
            k = K + 1
            fun = a - (k - 1) * (k - 1) * b
            if fun <= 0:
                break
            K = k

        if K == 0:
            continue

        # pre‑compute cumulative costs and values
        costs = [0] * (K + 1)
        values = [0] * (K + 1)
        for k in range(1, K + 1):
            costs[k] = k * t
            fun = a - (k - 1) * (k - 1) * b
            values[k] = values[k - 1] + fun

        # group knapsack (descending time)
        for time in range(maxT, -1, -1):
            best = dp[time]                     # take 0 rides from this group
            for k in range(1, K + 1):
                cost = costs[k]
                if cost > time:
                    break
                cand = dp[time - cost] + values[k]
                if cand > best:
                    best = cand
            dp[time] = best

    # turn exact‑time dp into prefix maximum
    for i in range(1, maxT + 1):
        if dp[i] < dp[i - 1]:
            dp[i] = dp[i - 1]

    # output answers
    out_lines = '\n'.join(str(dp[t]) for t in queries)
    sys.stdout.write(out_lines)

if __name__ == "__main__":
    solve()
